import java.util.ArrayList;
import java.util.List;
import sailpoint.object.Application;
import sailpoint.object.AttributeSource;
import sailpoint.object.AttributeTarget;
import sailpoint.object.ObjectAttribute;
import sailpoint.object.ObjectConfig;
import sailpoint.object.Rule;

String APP_NAME = "HR Authoritative CSV";

// { identity attribute, display name, type, application attribute }
String[][] MAPPINGS = {
    { "employeeNumber", "Employee Number", "string",  "employeeNumber" },
    { "firstname",      null,              "string",  "firstName"      },
    { "lastname",       null,              "string",  "lastName"       },
    { "manager",        null,              "sailpoint.object.Identity", "managerId" },
    { "inactive",       null,              "boolean", "inactive"       },
    { "startDate",      "Start Date",      "string",  "startDate"      },
    { "endDate",        "End Date",        "string",  "endDate"        },
    { "jobDescription", "Job Description", "string",  "jobDescription" },
    { "country",        "Country",         "string",  "country"        },
    { "employeeType",   "Employee Type",   "string",  "employeeType"   },
    { "isManager",      "Is Manager",      "string",  "isManager"      }
};

Application app = context.getObjectByName(Application.class, APP_NAME);
if (app == null) {
    return "ERROR: application '" + APP_NAME + "' not found. Import it first.";
}

ObjectConfig oc = context.getObjectByName(ObjectConfig.class, "Identity");
if (oc == null) {
    return "ERROR: ObjectConfig 'Identity' not found.";
}

List attrs = oc.getObjectAttributes();
if (attrs == null) {
    attrs = new ArrayList();
}

StringBuilder report = new StringBuilder();

for (int i = 0; i < MAPPINGS.length; i++) {
    String idAttr      = MAPPINGS[i][0];
    String displayName = MAPPINGS[i][1];
    String type        = MAPPINGS[i][2];
    String appAttr     = MAPPINGS[i][3];

    ObjectAttribute oa = oc.getObjectAttribute(idAttr);
    if (oa == null) {
        oa = new ObjectAttribute();
        oa.setName(idAttr);
        oa.setDisplayName(displayName != null ? displayName : idAttr);
        oa.setType(type);
        attrs.add(oa);
        report.append("Created identity attribute ").append(idAttr).append("\n");
    }

    // Calculated by a global rule (e.g. "inactive" after "Emergency Identity - Setup"):
    // a source would bypass the rule, so leave it alone
    if (oa.getRule() != null) {
        report.append("Skipped ").append(idAttr).append(" (calculated by global rule ")
              .append(oa.getRule().getName()).append(")\n");
        continue;
    }

    List sources = oa.getSources();
    if (sources == null) {
        sources = new ArrayList();
    }

    boolean exists = false;
    for (Object o : sources) {
        AttributeSource s = (AttributeSource) o;
        if (s.getApplication() != null
                && APP_NAME.equals(s.getApplication().getName())
                && appAttr.equals(s.getName())) {
            exists = true;
            break;
        }
    }

    if (exists) {
        report.append("Skipped ").append(idAttr).append(" (mapping already exists)\n");
    } else {
        AttributeSource src = new AttributeSource();
        src.setApplication(app);
        src.setName(appAttr);
        sources.add(src);
        oa.setSources(sources);
        report.append("Mapped ").append(idAttr).append(" <- ")
              .append(APP_NAME).append(":").append(appAttr).append("\n");
    }
}

// Lifecycle "status" identity attribute, calculated by a global rule
Rule statusRule = context.getObjectByName(Rule.class, "HR Lifecycle - Status Attribute");
if (statusRule == null) {
    return "ERROR: rule 'HR Lifecycle - Status Attribute' not found. Import it first.\n" + report;
}
ObjectAttribute statusAttr = oc.getObjectAttribute("status");
if (statusAttr == null) {
    statusAttr = new ObjectAttribute();
    statusAttr.setName("status");
    statusAttr.setDisplayName("Status");
    statusAttr.setType("string");
    attrs.add(statusAttr);
    report.append("Created identity attribute status\n");
}
statusAttr.setRule(statusRule);
report.append("status <- global rule HR Lifecycle - Status Attribute\n");

// displayName recalculated from the HR first/last name, so name changes show up
Rule displayNameRule = context.getObjectByName(Rule.class, "HR CSV - Display Name");
if (displayNameRule == null) {
    return "ERROR: rule 'HR CSV - Display Name' not found. Import it first.\n" + report;
}
ObjectAttribute dnAttr = oc.getObjectAttribute("displayName");
if (dnAttr == null) {
    dnAttr = new ObjectAttribute();
    dnAttr.setName("displayName");
    dnAttr.setDisplayName("Display Name");
    dnAttr.setType("string");
    attrs.add(dnAttr);
    report.append("Created identity attribute displayName\n");
}
dnAttr.setRule(displayNameRule);
report.append("displayName <- global rule HR CSV - Display Name\n");

// Target: push the identity displayName to the LDAP ApacheDS account's displayName
Application ldapApp = context.getObjectByName(Application.class, "LDAP ApacheDS");
if (ldapApp == null) {
    report.append("SKIPPED displayName -> LDAP ApacheDS (application not found, import it and run again)\n");
} else {
    List targets = dnAttr.getTargets();
    if (targets == null) targets = new ArrayList();
    boolean hasTarget = false;
    for (Object o : targets) {
        AttributeTarget t = (AttributeTarget) o;
        if (t.getApplication() != null && "LDAP ApacheDS".equals(t.getApplication().getName())
                && "displayName".equals(t.getName())) {
            hasTarget = true;
        }
    }
    if (hasTarget) {
        report.append("Skipped displayName -> LDAP ApacheDS:displayName (target already exists)\n");
    } else {
        AttributeTarget t = new AttributeTarget();
        t.setApplication(ldapApp);
        t.setName("displayName");
        targets.add(t);
        dnAttr.setTargets(targets);
        report.append("displayName -> LDAP ApacheDS:displayName (sync target)\n");
    }
}

// email <- LDAP ApacheDS:mail (address generated when the LDAP account is created)
if (ldapApp == null) {
    report.append("SKIPPED email <- LDAP ApacheDS:mail (application not found, import it and run again)\n");
} else {
    ObjectAttribute emailAttr = oc.getObjectAttribute("email");
    if (emailAttr == null) {
        emailAttr = new ObjectAttribute();
        emailAttr.setName("email");
        emailAttr.setDisplayName("Email");
        emailAttr.setType("string");
        attrs.add(emailAttr);
        report.append("Created identity attribute email\n");
    }
    List emailSources = emailAttr.getSources();
    if (emailSources == null) emailSources = new ArrayList();
    boolean hasMail = false;
    for (Object o : emailSources) {
        AttributeSource s = (AttributeSource) o;
        if (s.getApplication() != null && "LDAP ApacheDS".equals(s.getApplication().getName())
                && "mail".equals(s.getName())) {
            hasMail = true;
        }
    }
    if (hasMail) {
        report.append("Skipped email (mapping already exists)\n");
    } else {
        AttributeSource mailSrc = new AttributeSource();
        mailSrc.setApplication(ldapApp);
        mailSrc.setName("mail");
        emailSources.add(mailSrc);
        emailAttr.setSources(emailSources);
        report.append("Mapped email <- LDAP ApacheDS:mail\n");
    }
}

oc.setObjectAttributes(attrs);
context.saveObject(oc);
context.commitTransaction();

log.warn("HR CSV identity mapping setup:\n" + report.toString());
return report.toString();
